import React from "react";
import { Section, Container } from "@/components/layout/Shell";
import { cn } from "@/lib/utils";

export interface ImpactStat {
  value: string | number;
  suffix?: string;
  label: string;
}

interface ImpactStripProps {
  stats: ImpactStat[];
  className?: string;
  tone?: "default" | "alt" | "inverted";
}

export function ImpactStrip({
  stats,
  className,
  tone = "alt",
}: ImpactStripProps) {
  return (
    <Section tone={tone} className={cn("py-8 md:py-12 border-y border-border", className)}>
      <Container>
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-6 lg:gap-8 divide-y lg:divide-y-0 lg:divide-x divide-border">
          {stats.map((stat, idx) => (
            <div
              key={idx}
              className={cn(
                "flex flex-col justify-center",
                idx > 0 && idx % 2 === 0 ? "pt-6 lg:pt-0" : "",
                idx % 2 !== 0 ? "pt-6 sm:pt-0 pl-0 sm:pl-4 lg:pl-8" : "lg:first:pl-0 lg:pl-8"
              )}
            >
              <div className="flex items-baseline gap-0.5">
                <span className="font-serif text-3xl sm:text-4xl lg:text-5xl font-light tracking-tight text-foreground">
                  {stat.value}
                </span>
                {stat.suffix && (
                  <span className="font-serif text-2xl sm:text-3xl font-light text-primary">
                    {stat.suffix}
                  </span>
                )}
              </div>
              <p className="font-sans text-xs sm:text-sm text-muted-foreground font-medium tracking-wide mt-2">
                {stat.label}
              </p>
            </div>
          ))}
        </div>
      </Container>
    </Section>
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";

export type SectionTone = "default" | "alt" | "inverted";

export interface SectionProps extends React.HTMLAttributes<HTMLElement> {
  /**
   * The semantic tone of the section, determining background and text colors.
   * @default "default"
   */
  tone?: SectionTone;
}

/**
 * Section wrapper enforcing Nordic Lagom vertical rhythm: py-12 md:py-16 lg:py-20.
 */
export const Section = React.forwardRef<HTMLElement, SectionProps>(
  ({ tone = "default", className, children, ...props }, ref) => {
    const toneClasses = {
      default: "bg-background text-foreground",
      alt: "bg-muted text-foreground",
      inverted: "bg-foreground text-background",
    };

    return (
      <section
        ref={ref}
        data-tone={tone}
        className={cn(
          "py-12 md:py-16 lg:py-20",
          toneClasses[tone],
          className
        )}
        {...props}
      >
        {children}
      </section>
    );
  }
);
Section.displayName = "Section";

export type ContainerProps = React.HTMLAttributes<HTMLDivElement>;

/**
 * Container enforcing max-width of 1200px and strict gutter rules: 24px (32px >= xl).
 */
export const Container = React.forwardRef<HTMLDivElement, ContainerProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cn(
          "mx-auto w-full max-w-container px-4 sm:px-6 lg:px-8",
          className
        )}
        {...props}
      >
        {children}
      </div>
    );
  }
);
Container.displayName = "Container";
